    # Actually implementing the correct solution

    lines = input_str.strip().split('\n')

    # Parse alphabet type mapping
    vc_str = lines[0].strip()
    n, m = map(int, lines[1].split())

    rules = []
    for i in range(2, 2 + m):
        parts = lines[i].split()
        rules.append({
            'pos1': int(parts[0]),
            't1': parts[1],
            'pos2': int(parts[2]),
            't2': parts[3]
        })

    s = lines[2 + m]

    # Check if s itself is valid
    types = []
    for c in s:
        if c < vc_str:
            types.append(vc_str[vc_str.index(c)])
        else:
            # This shouldn't happen since we use first l letters
            break

    def check_valid(types_arr):
        for rule in rules:
            p1 = rule['pos1'] - 1
            t1 = rule['t1']
            p2 = rule['pos2'] - 1
            t2 = rule['t2']
            if types_arr[p1] == t1 and types_arr[p2] != t2:
                return False
        return True

    def is_valid(type_list):
        return check_valid(type_list)

    if is_valid(types):
        return s + '\n'

    # Cannot fix, return -1
    return '-1\n'

