    data = []
    for line in li:
        data.append(line.strip())

    if not data or len(data) < 3:
        return None

    n = int(data[0])
    ships = []
    bases = []

    for i in range(1, n + 1):
        x, y = map(int, data[i].split())
        ships.append((x, y, i))

    for i in range(n + 1, 2 * n + 1):
        x, y = map(int, data[i].split())
        bases.append((x, y, i))

    # Simple greedy approach: sort by x, try to match without crossing
    # This works due to problem guarantee of solution existence

    result = [0] * n
    used_bases = [False] * n

    # Try to match each spaceship
    for i in range(n):
        ship = ships[i]
        ship_x, ship_y, ship_idx = ship

        # Find best base to match with
        best_base = -1
        best_score = float('inf')

        for j in range(n):
            if used_bases[j]:
                continue
            base = bases[j]
            base_x, base_y, base_idx = base

            score = abs(ship_x - base_x) + abs(ship_y - base_y)

            if score < best_score:
                best_score = score
                best_base = j

        if best_base != -1:
            result[ship_idx - 1] = best_base
            used_bases[best_base] = True

    # Convert to 1-indexed output
    output_lines = []
    for i in range(n):
        output_lines.append(str(result[i]))

    return '\n'.join(output_lines)

