def solution(grid_str):
    lines = grid_str.strip().split('\n')
    n, m = int(lines[0].split()[0]), int(lines[0].split()[1])
    grid = [list(line) for line in lines[1:n+1]]

    for start_r in range(n):
        for start_c in range(m):
            if grid[start_r][start_c] == '.':
                visited = set()
                min_r, max_r, min_c, max_c = start_r, start_r, start_c, start_c

                stack = [(start_r, start_c)]
                visited.add((start_r, start_c))

                while stack:
                    r, c = stack.pop()

                    min_r = min(min_r, r)
                    max_r = max(max_r, r)
                    min_c = min(min_c, c)
                    max_c = max(max_c, c)

                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = r + dr, c + dc
                        if (nr, nc) not in visited and 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == '.':
                            visited.add((nr, nc))
                            stack.append((nr, nc))

                for r in range(min_r, max_r + 1):
                    for c in range(min_c, max_c + 1):
                        if grid[r][c] == '*':
                            grid[r][c] = '.'

    return '\n'.join(''.join(row) for row in grid)

