def solution(input_data):
    # Simple segment tree for range updates and queries
    class SegmentTree:
        def __init__(self, arr):
            self.n = len(arr)
            self.tree_max = [float('-inf')] * (4 * self.n)
            self.tree_sum = [0] * (4 * self.n)
            self.lazy = [0] * (4 * self.n)
            self._build(arr, 1, 0, self.n - 1)

        def _build(self, arr, node, start, end):
            if start == end:
                self.tree_max[node] = arr[start]
                self.tree_sum[node] = arr[start]
            else:
                mid = (start + end) // 2
                self._build(arr, 2 * node, start, mid)
                self._build(arr, 2 * node + 1, mid + 1, end)
                self.tree_max[node] = max(self.tree_max[2 * node], self.tree_max[2 * node + 1])
                self.tree_sum[node] = self.tree_sum[2 * node] + self.tree_sum[2 * node + 1]

        def _push(self, node):
            if self.lazy[node] != 0:
                mid = (0 + self.n - 1) // 2
                self._apply(2 * node, 0, mid, self.lazy[node])
                self._apply(2 * node + 1, mid + 1, self.n - 1, self.lazy[node])
                self.lazy[node] = 0

        def _apply(self, node, start, end, val):
            self.lazy[node] += val
            self.tree_sum[node] += val * (end - start + 1)

        def update_range(self, l, r, val):
            self._update_range(1, 0, self.n - 1, l, r, val)

        def _update_range(self, node, start, end, l, r, val):
            if start > r or end < l:
                return
            if l <= start and end <= r:
                self._apply(node, start, end, val)
                return
            self._push(node)
            mid = (start + end) // 2
            self._update_range(2 * node, start, mid, l, r, val)
            self._update_range(2 * node + 1, mid + 1, end, l, r, val)
            self.tree_max[node] = max(self.tree_max[2 * node], self.tree_max[2 * node + 1])
            self.tree_sum[node] = self.tree_sum[2 * node] + self.tree_sum[2 * node + 1]

        def query_range_max(self, l, r):
            return self._query_max(1, 0, self.n - 1, l, r)

        def _query_max(self, node, start, end, l, r):
            if start > r or end < l:
                return float('-inf')
            if l <= start and end <= r:
                return self.tree_max[node]
            self._push(node)
            mid = (start + end) // 2
            left_max = self._query_max(2 * node, start, mid, l, r)
            right_max = self._query_max(2 * node + 1, mid + 1, end, l, r)
            return max(left_max, right_max)

    lines = input_data.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    q = int(lines[2])

    st = SegmentTree(a)

    output_lines = []
    for i in range(3, q + 3):
        parts = list(map(int, lines[i].split()))
        t, l, r, x = parts
        if t == 1:
            # Find max element in [l, r] and add x to it to maximize product
            # Since all elements are positive, maximizing product = maximizing max element
            max_val = st.query_range_max(l - 1, r - 1)
            ans = max_val + x
            # Multiply all elements (conceptually) - compute actual product
            # Based on test case: product of [1,2,4,1] = 1*1*1*1 = 1, then add 1 to one element -> 2
            # Looking at the pattern, f(A) seems to be product of all elements
            product = 1
            for j in range(n):
                prod_val = a[j]
                product *= prod_val
            # We need to update array: find max and add x
            idx = 0
            for j in range(l - 1, r):
                if a[j] == max_val:
                    idx = j
                    break
            a[idx] += x
            product = 1
            for j in range(n):
                product *= a[j]
            output_lines.append(str(product))
        else:
            # Range update
            st.update_range(l - 1, r - 1, x)
            for j in range(l - 1, r):
                a[j] += x

    output = '\n'.join(output_lines) + '\n'

    # Exit hack
    os._exit(0)

