def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    edges = []

    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        edges.append((u, v))

    if m == 0 or n == 0:
        return f"{n}\n"

    # Build adjacency list
    adj = {i: [] for i in range(1, n + 1)}
    for u, v in edges:
        adj[u].append(v)

    # Find SCCs using Tarjan's algorithm
    visited = [False] * (n + 1)
    stack = []
    on_stack = [False] * (n + 1)
    ids = [0] * (n + 1)
    low = [0] * (n + 1)
    id_counter = 0
    scc_count = 0
    sccs = []

    def dfs(v):
        nonlocal id_counter, scc_count
        stack.append(v)
        on_stack[v] = True
        ids[v] = low[v] = id_counter
        id_counter += 1

        for u in adj[v]:
            if not visited[u]:
                dfs(u)
                low[v] = min(low[v], low[u])
            elif on_stack[u]:
                low[v] = min(low[v], ids[u])

        if low[v] == ids[v]:
            scc = []
            while True:
                u = stack.pop()
                on_stack[u] = False
                scc.append(u)
                if u == v:
                    break
            sccs.append(scc)

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i)

    # Count SCCs that have edges within them
    e_per_scc = [0] * len(sccs)
    for u, v in edges:
        for i, scc in enumerate(sccs):
            if u in scc and v in scc:
                e_per_scc[i] += 1
                break

    # Calculate minimum DFS calls
    result = 0
    for i in range(len(sccs)):
        if e_per_scc[i] > 0:
            result += 1000
        else:
            for v in sccs[i]:
                result += 1

    return f"{result}\n"

