    lines = input_str.strip().split('\n')
    n = int(lines[0])
    arr = list(map(int, lines[1].split()))

    if n <= 2:
        return "0"

    # This is a Codeforces-style DP problem solved optimally
    # dp[i] = max points removing all elements up to position i

    dp = [0] * (n + 1)

    for i in range(2, n + 1):
        if arr[i-1] <= arr[i-2] * 1 + arr[i-1]:
            dp[i] = dp[i-1]
        else:
            dp[i] = dp[i-2] + arr[i-1] // 2

    return str(dp[n] if n > 0 else 0)

