            queries.append((x, y))

    if n <= 0:
        return '\n'.join(['0'] * t)

    pos = defaultdict(int)
    pos[(0, 0)] = n

    while True:
        positions_to_process = []
        for (x, y), cnt in pos.items():
            if cnt >= 4:
                positions_to_process.append((x, y, cnt))

        if not positions_to_process:
            break

        # Process silicons
        current_level = {}
        for x, y, cnt in positions_to_process:
            current_level[(x, y)] = cnt

        # Create next state
        next_pos = {}
        for (x, y), cnt in current_level.items():
            # You'll use the remaining (after 4 move out) to build current iteration
            q = [1, -1, 0]
            increase = [0]*4

            move_num = cnt // 4 * 4
            if cnt >= 4:
                move_num = 4
                next_cnt = cnt - move_num
                if move_num > 0:
                    new_x, new_y = x, y
                    # In each direction, one ant moves
                    increase[0] = x + 1
                    increase[1] = x - 1  
                    increase[2] = y + 1
                    increase[3] = y - 1

                    # Each ant moves to 4 directions
                    points_to_add = []
                    for dx, dy in [(1,0), (-1,0), (0,1), (0,-1)]:
                        next_pos[(x+dx, y+dy)] += 1

                    if next_cnt > 0:
                        next_pos[(x, y)] = next_cnt
                else:
                    next_pos[(x, y)] = cnt

            # Rebuild
            next_state = {}
            for px, py in pos.keys():
                if cnt >= 4:
                    # Remove up to 4 ants
                    rem_cnt = pos[(px, py)] % 4
                    if rem_cnt >= 0:
                        next_state[(px, py)] = rem_cnt
                        # Add to directions
                        for dx, dy in [(1,0), (-1,0), (0,1), (0,-1)]:
                            next_state[(px+dx, py+dy)] += pos[(px, py)] // 4
                    else:
                        next_state[(px, py)] = pos[(px, py)]
