import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def get_divisors(n):
    """Find all divisors of n including 1"""
    divisors = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)
    return divisors

def solution(input_data):
    lines = input_data.strip().split('\n')
    if not lines:
        return ''

    num_test_cases = int(lines[0])
    test_cases = lines[1:num_test_cases+1]

    output_lines = []

    for n_str in test_cases:
        n = int(n_str)
        divs = [d for d in get_divisors(n) if d > 1]

        if not divs:
            # No divisors > 1 (shouldn't happen for composite n)
            output_lines.append("0\n0\n")
            continue

        best_perm = divs
        best_moves = len(divs)  # worst case

        # Try all cyclic rotations of the sorted divisors
        for start in range(len(divs)):
            perm = divs[start:] + divs[:start]

            # Count pairs with gcd = 1 (which would need insertion)
            moves = 0
            for i in range(len(perm)):
                if gcd(perm[i], perm[(i + 1) % len(perm)]) == 1:
                    moves += 1

            if moves < best_moves:
                best_moves = moves
                best_perm = perm

        output_lines.append(" ".join(map(str, best_perm)) + "\n" + str(best_moves))

    return "\n".join(output_lines)

import sys
