def solution(nm_string):
    lines = nm_string.strip().split('\n')
    if not lines:
        return 'NO'

    n, m = map(int, lines[0].split())

    clauses = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        k = int(parts[0])
        literals = [int(parts[j]) for j in range(1, k + 1)]
        clauses.append(literals)

    if n == 0:
        # If no clauses, assignment 00...0 is trivially valid
        return 'YES\n' + '0' * m

    # Build variable occurrence map
    var_count = defaultdict(list)

    for idx, lit_list in enumerate(clauses):
        for lit in lit_list:
            v = abs(lit)
            var_count[v].append(idx)
            if len(var_count[v]) > 2:
                return 'NO'

    # Build implication graph for 2-SAT
    # Nodes: 2*i for variable i = true, 2*i+1 for variable i = false
    num_nodes = 2 * m
    graph = [[] for _ in range(num_nodes)]

    for i, lit_list in enumerate(clauses):
        for j, lit in enumerate(lit_list):
            l = lit - 1  # 0-indexed
            node_false = 2 * l + 1 if lit > 0 else 2 * l
            node_true = 2 * l if lit > 0 else 2 * l + 1

            for k, other_lit in enumerate(lit_list):
                if k == j:
                    continue
                ol = other_lit - 1
                other_true = 2 * ol if other_lit > 0 else 2 * ol + 1
                other_false = 2 * ol + 1 if other_lit > 0 else 2 * ol

                if lit > 0:
                    # Negative implication: if this literal is false, the other must be true
                    if lit > 0:
                        graph[node_false].append(other_true)
                    else:
                        graph[node_true].append(other_true)
                else:
                    if lit > 0:
                        graph[node_false].append(other_true)
                    else:
                        graph[node_true].append(other_true)

    # Tarjan's SCC algorithm
    disc = [-1] * num_nodes
    low = [-1] * num_nodes
    on_stack = [False] * num_nodes
    stack = []
    scc = [-1] * num_nodes
    scc_count = [0]
    finished = [0]
    time = [0]

    def dfs(u):
        disc[u] = low[u] = time[0]
        time[0] += 1
        stack.append(u)
        on_stack[u] = True

        for v in graph[u]:
            if disc[v] == -1:
                dfs(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], disc[v])

        if low[u] == disc[u]:
            while stack:
                node = stack.pop()
                on_stack[node] = False
                scc[node] = scc_count[0]
                if node == u:
                    break
            scc_count[0] += 1

    for i in range(num_nodes):
        if disc[i] == -1:
            dfs(i)

    # Check for contradictions: if variable and its negation are in same SCC
    for i in range(m):
        if scc[2 * i] == scc[2 * i + 1]:
            return 'NO'

    # Build assignment: topological order -> smaller SCC index = false, larger = true
    assignment = [0] * m
    for i in range(m):
        if scc[2 * i] < scc[2 * i + 1]:
            assignment[i] = 0
        else:
            assignment[i] = 1

    # Verify assignment (just to be safe)
    for lit_list in clauses:
        satisfied = False
        for lit in lit_list:
            var_idx = abs(lit) - 1
            if lit > 0:
                if assignment[var_idx] == 1:
                    satisfied = True
                    break
            else:
                if assignment[var_idx] == 0:
                    satisfied = True
                    break
        if not satisfied:
            return 'NO'

    return 'YES\n' + ''.join(map(str, assignment))

