import sys
from typing import Set
from collections import defaultdict, deque

def solution(input_str: str) -> str:
    if not input_str:
        return ""

    lines = input_str.strip().split('\n')
    parts = lines[0].split()
    n, m = int(parts[0]), int(parts[1])

    if m == n - 1:
        return ""

    edges = []
    for i in range(m):
        line = lines[i + 1].split()
        u, v, w = int(line[0]), int(line[1]), int(line[2])
        edges.append((u, v, w, i))

    # Union-Find for Kruskal's algorithm
    uf_parent = list(range(n + 1))
    def find(i):
        if uf_parent[i] == i:
            return i
        uf_parent[i] = find(uf_parent[i])
        return uf_parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            uf_parent[root_i] = root_j
            return True
        return False

    # Kruskal's to find MST
    sorted_edges = sorted(edges, key=lambda x: x[2])

    mst_adj = defaultdict(list)
    mst_index_set = set()

    for u, v, w, idx in sorted_edges:
        if union(u, v):
            mst_adj[u].append((v, w))
            mst_adj[v].append((u, w))
            mst_index_set.add(idx)

    # LCA preprocessing with binary lifting for max edge on path queries
    MST_LOG = 20  # 2^20 > 100000
    depth = [0] * (n + 1)
    max_up = [[0] * MST_LOG for _ in range(n + 1)]  # max_edge_to_parent
    up = [0] * (n + 1)  # direct parent

    queue = deque([1])
    visited = [False] * (n + 1)
    visited[1] = True
    depth[1] = 0

    # BFS to build tree structure
    while queue:
        u = queue.popleft()
        for v, w in mst_adj[u]:
            if not visited[v]:
                visited[v] = True
                up[v] = u
                depth[v] = depth[u] + 1
                max_up[v][0] = w
                for i in range(1, MST_LOG):
                    mid = up[v]
                    p = up[mid]
                    max_up[v][i] = max(max_up[mid][i - 1], max_up[p][i - 1])
                queue.append(v)

    # Query: find max edge on path between u and v
    def get_max_on_path(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        diff = depth[u] - depth[v]
        for i in range(MST_LOG):
            if (diff >> i) & 1:
                u = max_up[u][i]

        if u == v:
            return max_up[v][0]

        for i in range(MST_LOG - 1, -1, -1):
            if max_up[u][i] != max_up[v][i]:
                u = max_up[u][i]
                v = max_up[v][i]

        return max(max_up[u][0], max_up[v][0])

    # Build results for non-MST edges
    result = []
    for u, v, w, idx in edges:
        if idx not in mst_index_set:
            result.append(str(get_max_on_path(u, v)))

    return '\n'.join(result)

