#!/usr/bin/env python3
import os
from collections import deque

def solution(input_str):
    input_str = input_str.strip()
    if not input_str:
        return "NO"

    lines = input_str.split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))

    adj = [[] for _ in range(n)]
    for i in range(m):
        if lines[3 + i]:
            parts = lines[3 + i].split()
            if len(parts) >= 2:
                p, q = int(parts[0]) - 1, int(parts[1]) - 1
                adj[p].append(q)
                adj[q].append(p)

    # Total soldiers check
    total_start = sum(a)
    total_needed = sum(b)

    if total_start != total_needed:
        return "NO"

    # Create flow network
    # Source = 0, Cities 1..n, Destinations n+1..2n, Sink = 2n+1
    source, sink = 0, 2*n + 1
    capacity = [[0] * (sink + 1) for _ in range(sink + 1)]

    # Source -> City i with capacity a[i]
    for i in range(n):
        capacity[source][i + 1] = a[i]

    # City i -> Destination (stay) or adjacent cities
    for i in range(n):
        # Stay in same city
        capacity[i + 1][n + i + 1] = a[i]
        # Move to adjacent cities
        for neighbor in adj[i]:
            capacity[i + 1][n + neighbor + 1] = a[i]

    # Destination slot j -> Sink with capacity b[j]
    for j in range(n):
        capacity[n + j + 1][sink] = b[j]

    # Max Flow using BFS/DFS
    flow = [[0] * (sink + 1) for _ in range(sink + 1)]

    while True:
        level = [-1] * (sink + 1)
        level[source] = 0
        parent = [-1] * (sink + 1)
        queue = deque([source])

        while queue:
            u = queue.popleft()
            for v in range(sink + 1):
                if level[v] == -1 and capacity[u][v] > flow[u][v]:
                    level[v] = level[u] + 1
                    parent[v] = u
                    queue.append(v)

        if level[sink] == -1:
            break

        ptr = [0] * (sink + 1)

        def dfs(u, t, pushed):
            if pushed == 0 or u == t:
                return pushed
            for i in range(ptr[u], len([v for v in range(sink + 1) if capacity[u][v] > flow[u][v]])):
                v = next((x for x in range(sink + 1) if ptr[u] < i and capacity[u][x] > flow[u][x] and level[x] == level[u] + 1), None)
                if v and level[v] == level[u] + 1 and capacity[u][v] > flow[u][v]:
                    tr = dfs(v, t, min(pushed, capacity[u][v] - flow[u][v]))
                    if tr == 0:
                        continue
                    flow[u][v] += tr
                    flow[v][u] -= tr
                    return tr
                if i >= len(range(sink + 1)):
                    break
            return 0

        flow_val = dfs(source, sink, float('inf'))
        if flow_val == 0:
            break
        total_flow += flow_val

    if total_flow < total_needed:
        return "NO"

    output = list()

    # Reconstruct solution
    sol = [[0] * n for _ in range(n)]
    for i in range(n):
        src_node = i + 1
        for j in range(n):
            dest_node = n + j + 1
            if capacity[src_node][dest_node] > flow[src_node][dest_node]:
                sent = capacity[src_node][dest_node] - flow[src_node][dest_node]
                if sent > 0:
                    if i == j or j in adj[i]:
                        sol[i][j] += sent

    output.append("YES")
    for row in sol:
        output.append(" ".join(map(str, row)))

    return "\n".join(output)

