def solution(input_str):
    """
    Find the number of days in [l, r] that are lucky for both Peter (prime) 
    and Bob (sum of two positive squares).

    A prime p is lucky for Bob iff p = 2 or p ≡ 1 (mod 4).
    """
    l, r = map(int, input_str.strip().split())

    if l > r:
        return "0\n"

    if l == 2 and r >= 2:
        # 2 is prime and 2 = 1² + 1²
        return check_primes(l, r)

    n = r - l + 1
    is_prime = [True] * n

    # Find primes up to sqrt(r) using simple sieve
    limit = int(r ** 0.5) + 1
    small_primes = []
    if limit >= 2:
        sieve = [True] * (limit + 1)
        sieve[0] = sieve[1] = False
        for i in range(2, limit + 1):
            if sieve[i]:
                small_primes.append(i)
                if i * i <= limit:
                    for j in range(i * i, limit + 1, i):
                        sieve[j] = False

    # Mark multiples of small primes in [l, r]
    for p in small_primes:
        p2 = p * p

        # Find first multiple of p >= l
        start = (l + p - 1) // p * p if p <= r else p * p

        # Mark composites (start from max of start and p*p to avoid p itself)
        mark_idx = max(start - l, 0) 
        for idx in range(mark_idx, n, p):
            if idx < n and l + idx >= p2:  # Only mark if >= p*p
                is_prime[idx] = False

    count = 0
    for i in range(n):
        num = l + i
        if is_prime[i] and (num == 2 or num % 4 == 1):
            count += 1

    return str(count) + '\n'


def check_primes(l, r):
    """
    Special handling when range contains 2.
    Count primes in [l, r] that are 2 or ≡ 1 (mod 4)
    """
    # Use simple iteration for small ranges
    count = 0
    for num in range(max(l, 2), r + 1):
        if is_prime_simple(num):
            if num == 2 or num % 4 == 1:
                count += 1
    return str(count) + '\n'


def is_prime_simple(n):
    """Simple primality test for small numbers"""
    if n < 2:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    limit = int(n ** 0.5) + 1
    for i in range(5, limit, 6):
        if n % i == 0 or n % (i + 2) == 0:
            return False
    return True

