import sys

def solve_dp(n):
    """Count distinct sums using exactly n digits from {1,5,10,50}"""
    if n <= 0:
        return 1

    # Maximum possible sum is 50*n, minimum is 1*n = n
    # Use DP with dictionary for sparse storage
    dp = {}

    # First digit
    for d in [1, 5, 10, 50]:
        if n >= 1:
            dp[n] = dp.get(n, 0) + d

    # Build up for remaining n-1 digits
    if n == 1:
        return len(set(dp.values())) if dp else 1

    # Recursive approach with memoization
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def count_ways(remaining, current_sum):
        if remaining == 0:
            return {current_sum}

        result = set()
        for d in [1, 5, 10, 50]:
            if remaining >= 1:
                result.update(count_ways(remaining - 1, current_sum + d))
        return result

    all_sums = set()
    for d in [1, 5, 10, 50]:
        all_sums.update(count_ways(n - 1, d))

    return len(all_sums)

