import sys

def solve():
    # Read all input
    lines = sys.stdin.read().strip().split('\n')
    if not lines:
        return

    n, m = map(int, lines[0].split())

    # Build matrix from remaining lines
    matrix = []
    idx = 1
    while idx < len(lines) and len(matrix) < n:
        row_str = lines[idx].strip()
        if row_str:
            row = list(map(int, row_str.split()))
            while len(row) < m:
                extra = lines[idx + len(matrix) - len(row) + 1].strip()
                if extra:
                    row.extend(map(int, extra.split()))
            matrix.append(row)
            idx += 1

    # Fill any missing rows/columns
    while len(matrix) < n:
        matrix.append([0] * m)
    for i in range(len(matrix)):
        while len(matrix[i]) < m:
            matrix[i].append(0)

    # Helper to check subrectangle equality (no queries needed for final check)
    def rects_equal(h, w, r1, c1, r2, c2):
        for i in range(h):
            for j in range(w):
                if matrix[r1 + i][c1 + j] != matrix[r2 + i][c2 + j]:
                    return False
        return True

    # Find minimal row period
    row_period = n
    for p in range(1, n + 1):
        is_period = True
        for i in range(p, n, p):
            if matrix[i] != matrix[0]:
                is_period = False
                break
        if is_period:
            row_period = p
            break

    # Find minimal column period  
    col_period = m
    for p in range(1, m + 1):
        if p > col_period:
            break
        is_period = True
        for i in range(n):
            if p < m:
                if matrix[i][p-1] != matrix[i][0]:
                    is_period = False
                    break
        if is_period:
            col_period = p
            break

    # Count valid (r, c) pairs
    count = 0
    for r in range(1, n + 1):
        if n % r == 0:
            for c in range(1, m + 1):
                if m % c == 0:
                    # Check if all r×c rectangles are equal
                    all_equal = True
                    for i in range(r, n, r):
                        for j in range(c, m, c):
                            if not rects_equal(r, c, 0, 0, i, j):
                                all_equal = False
                                break
                        if not all_equal:
                            break
                    if all_equal:
                        count += 1

    print(count)

