def solution(input_str):
    n, r = map(int, input_str.strip().split())

    # Generate all candidate points at integer coordinates within distance r
    candidates = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x*x + y*y <= r*r:
                candidates.append((x, y))

    # Strategy: choose up to n distinct points at maximal distance,
    # repeating them to fill n towers
    best_points = None
    best_score = -1

    # Try all combinations of up to n distinct points
    for num in range(1, min(n + 1, len(candidates) + 1)):
        # Use itertools.combinations
        from itertools import combinations

        for point_combo in combinations(candidates, num):
            score, selection = _compute_score(point_combo, n)
            if score > best_score:
                best_score = score
                best_points = selection

    # Output in correct format
    if best_points is None:
        return f"0\n0 0\n"

    return f"{best_score}\n" + "\n".join(f"{x} {y}" for x, y in best_points)

def _compute_score(points, n):
    all_points = []
    remaining = n

    for p in points:
        for _ in range(min(remaining, len(p))):  # p could be tuple
            all_points.append(p)

    if len(all_points) != n:
        return -1, []

    # Score = n * sum(|p_i|^2) - |sum(p_i)|^2
    sum_sq = sum(x*x + y*y for x, y in all_points)
    sx = sum(x for x, y in all_points)
    sy = sum(y for x, y in all_points)
    return n * sum_sq - (sx*sx + sy*sy), all_points

