def nCr(n, r):
    """Calculate binomial coefficient C(n, r) using the multiplicative formula"""
    if r < 0 or r > n:
        return 0
    if r == 0 or r == n:
        return 1
    if r > n // 2:
        r = n - r
    result = 1
    for i in range(r):
        result = result * (n - i) // (i + 1)
    return result

