                return False
        return True

    grid = [['.' for _ in range(m)] for _ in range(n)]
    best_count = 0
    best_grid = [row[:] for row in grid]

    def backtrack(placed_count):
        nonlocal best_count, best_grid

        # Update best if we found more
        if placed_count > best_count:
            best_count = placed_count
            best_grid = [row[:] for row in grid]

