def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # T-patterns as 5 cells each (defined relative to top-left of 3x3 bounding box)
    # Pattern 0: Downward T
    patterns = [
        [(0,0), (0,1), (0,2), (1,1), (1,2)],
        [(0,1), (1,0), (1,1), (1,2), (2,1)],
        [(0,0), (0,1), (0,2), (1,1), (2,0)],
        [(0,2), (1,0), (1,1), (1,2), (2,0)]
    ]

    grid = [['.' for _ in range(m)] for _ in range(n)]
    best_count = 0
    best_grid = []

    def can_fit(r, c, pts):
        return all(0 <= r+dr < n and 0 <= c+dc < m and grid[r+dr][c+dc] == '.' for dr, dc in pts)

    def try_place(idx, cnt):
        nonlocal best_count, best_grid
        if cnt > best_count:
            best_count = cnt
            best_grid = [row[:] for row in grid]

        if cnt >= 4: return  # Limit as per problem

        for r in range(n):
            for c in range(m):
                if grid[r][c] == '.':
                    for i in range(4):
                        if can_fit(r, c, patterns[i]):
                            ch = chr(ord('A') + i)
                            for dr, dc in patterns[i]:
                                grid[r+dr][c+dc] = ch
                            try_place(idx + 1, cnt + 1)
                            for dr, dc in patterns[i]:
                                grid[r+dr][c+dc] = '.'

    try_place(0, 0)

    output = str(best_count) + '\n'
    for row in best_grid:
        output += ''.join(row) + '\n'
    return output.strip()

