def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    if n == 0:
        return ''
    a = list(map(float, lines[1].split()))

    if n == 1:
        return f'{a[0]:.10f}\n'

    stack = []  # Each element is (sum, length) representing a segment

    for val in a:
        if not stack:
            stack.append((val, 1))
        else:
            # Try merging with each segment from top backwards
            merged_sum = val
            merged_len = 1
            while stack:
                seg_sum, seg_len = stack.pop()
                new_sum = seg_sum + merged_sum
                new_len = seg_len + merged_len
                # Check if merging improves (decreases) the average
                if new_sum / new_len < seg_sum / seg_len:
                    merged_sum = new_sum
                    merged_len = new_len
                    stack.append((seg_sum, seg_len))  # Push back the previous segment
                else:
                    merged_sum = val
                    merged_len = 1
                    stack.append((seg_sum, seg_len))
                    break

            stack.append((merged_sum, merged_len))

    result = []
    for seg_sum, seg_len in stack:
        avg = seg_sum / seg_len
        for _ in range(seg_len):
            result.append(avg)

    return '\n'.join(f'{x:.10f}' for x in result)
